param(
  [string]$ProjectRoot = (Get-Location).Path
)

$ErrorActionPreference = "Stop"

if (-not (Test-Path (Join-Path $ProjectRoot "package.json"))) {
  throw "Execute este script a partir da raiz do Studio RD Black, onde existe package.json."
}

$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot ".studio-rd-backup-correcao-servico-$Timestamp"
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)

function Backup-File([string]$RelativePath) {
  $Source = Join-Path $ProjectRoot $RelativePath

  if (Test-Path $Source) {
    $Destination = Join-Path $BackupRoot $RelativePath
    New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
    Copy-Item -Force $Source $Destination
  }
}

function Write-EmbeddedFile([string]$RelativePath, [string]$Base64Content) {
  $Destination = Join-Path $ProjectRoot $RelativePath
  Backup-File $RelativePath
  New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
  $Content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
  [System.IO.File]::WriteAllText($Destination, $Content, $Utf8NoBom)
  Write-Host ("OK  " + $RelativePath) -ForegroundColor Green
}

function Read-Utf8([string]$RelativePath) {
  $Path = Join-Path $ProjectRoot $RelativePath
  if (-not (Test-Path $Path)) {
    throw "Arquivo não encontrado: $Path"
  }
  return [System.IO.File]::ReadAllText($Path)
}

function Write-Utf8([string]$RelativePath, [string]$Content) {
  $Path = Join-Path $ProjectRoot $RelativePath
  Backup-File $RelativePath
  [System.IO.File]::WriteAllText($Path, $Content, $Utf8NoBom)
  Write-Host ("OK  " + $RelativePath) -ForegroundColor Green
}

Write-Host "Studio RD Black - correção de serviço em até 7 dias" -ForegroundColor Cyan
Write-Host "Projeto: $ProjectRoot"
Write-Host ""

# 1) Novos arquivos
Write-EmbeddedFile "src\components\agenda\CorrecoesServicoPage.tsx" ""
Write-EmbeddedFile "src\routes\funcionario.correcoes.tsx" ""
Write-EmbeddedFile "src\routes\admin.correcoes.tsx" ""

# 2) Backend de agendamento
$ApiPath = "src\lib\api\agendamento.functions.ts"
$Api = Read-Utf8 $ApiPath

if ($Api -notmatch "operacionalCorrigirServicoConcluido") {
  $MarkerSchema = 'const TIMEZONE_PADRAO = "America/Sao_Paulo";'
  if (-not $Api.Contains($MarkerSchema)) {
    throw "Não encontrei o marcador TIMEZONE_PADRAO em agendamento.functions.ts."
  }

  $SchemaInsert = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
  $Api = $Api.Replace($MarkerSchema, $SchemaInsert + $MarkerSchema)

  $MarkerHandler = "export const funcionarioConcluirAgendamento ="
  if (-not $Api.Contains($MarkerHandler)) {
    throw "Não encontrei funcionarioConcluirAgendamento em agendamento.functions.ts."
  }

  $ServerInsert = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
  $Api = $Api.Replace($MarkerHandler, $ServerInsert + $MarkerHandler)

  Write-Utf8 $ApiPath $Api
} else {
  Write-Host "SKIP  backend de correção já existe" -ForegroundColor Yellow
}

# 3) Navegação do funcionário
$FuncionarioPath = "src\routes\funcionario.tsx"
$Funcionario = Read-Utf8 $FuncionarioPath

if ($Funcionario -notmatch 'to: "/funcionario/correcoes"') {
  if ($Funcionario -notmatch '(?m)^\s*History,\s*$') {
    $Funcionario = $Funcionario.Replace(
      "  CalendarX2,`r`n  LayoutDashboard,",
      "  CalendarX2,`r`n  History,`r`n  LayoutDashboard,"
    )
    $Funcionario = $Funcionario.Replace(
      "  CalendarX2,`n  LayoutDashboard,",
      "  CalendarX2,`n  History,`n  LayoutDashboard,"
    )
  }

  $FuncionarioMarker = @'
  {
    label: "Bloqueios",
    to: "/funcionario/bloqueios",
    icon: CalendarX2,
  },
'@

  # Here-string above uses doubled braces because of Python formatting; normalize them.
  $FuncionarioMarker = $FuncionarioMarker.Replace("{", "{").Replace("}", "}")
  # Simpler literal reconstruction:
  $FuncionarioMarker = "  {`n    label: `"Bloqueios`",`n    to: `"/funcionario/bloqueios`",`n    icon: CalendarX2,`n  },"
  if (-not $Funcionario.Contains($FuncionarioMarker)) {
    $FuncionarioMarker = "  {`r`n    label: `"Bloqueios`",`r`n    to: `"/funcionario/bloqueios`",`r`n    icon: CalendarX2,`r`n  },"
  }

  if (-not $Funcionario.Contains($FuncionarioMarker)) {
    throw "Não encontrei o item Bloqueios na navegação do funcionário."
  }

  $NovoItem = "  {`n    label: `"Correções`",`n    to: `"/funcionario/correcoes`",`n    icon: History,`n  },`n"
  if ($FuncionarioMarker.Contains("`r`n")) {
    $NovoItem = $NovoItem.Replace("`n", "`r`n")
  }

  $Funcionario = $Funcionario.Replace($FuncionarioMarker, $NovoItem + $FuncionarioMarker)
  Write-Utf8 $FuncionarioPath $Funcionario
} else {
  Write-Host "SKIP  menu de correções do funcionário já existe" -ForegroundColor Yellow
}

# 4) Navegação do admin
$AdminPath = "src\routes\admin.tsx"
$Admin = Read-Utf8 $AdminPath

if ($Admin -notmatch 'to: "/admin/correcoes"') {
  if ($Admin -notmatch '(?m)^\s*History,\s*$') {
    $Admin = $Admin.Replace(
      "  DollarSign,`r`n  LayoutDashboard,",
      "  DollarSign,`r`n  History,`r`n  LayoutDashboard,"
    )
    $Admin = $Admin.Replace(
      "  DollarSign,`n  LayoutDashboard,",
      "  DollarSign,`n  History,`n  LayoutDashboard,"
    )
  }

  $AdminMarker = "  {`n    label: `"Bloqueios`",`n    to: `"/admin/bloqueios`",`n    icon: CalendarX2,`n  },"
  if (-not $Admin.Contains($AdminMarker)) {
    $AdminMarker = "  {`r`n    label: `"Bloqueios`",`r`n    to: `"/admin/bloqueios`",`r`n    icon: CalendarX2,`r`n  },"
  }

  if (-not $Admin.Contains($AdminMarker)) {
    throw "Não encontrei o item Bloqueios na navegação do admin."
  }

  $NovoAdminItem = "  {`n    label: `"Correções`",`n    to: `"/admin/correcoes`",`n    icon: History,`n  },`n"
  if ($AdminMarker.Contains("`r`n")) {
    $NovoAdminItem = $NovoAdminItem.Replace("`n", "`r`n")
  }

  $Admin = $Admin.Replace($AdminMarker, $NovoAdminItem + $AdminMarker)
  Write-Utf8 $AdminPath $Admin
} else {
  Write-Host "SKIP  menu de correções do admin já existe" -ForegroundColor Yellow
}

Write-Host ""
Write-Host "Implementação aplicada." -ForegroundColor Green
Write-Host ("Backup: " + $BackupRoot) -ForegroundColor Yellow
Write-Host ""
Write-Host "Regras implementadas:" -ForegroundColor Cyan
Write-Host "  - somente atendimentos CONCLUIDOS"
Write-Host "  - somente atendimentos dos ultimos 7 dias"
Write-Host "  - altera apenas servicoId + auditoria interna"
Write-Host "  - preserva inicio, fim, forma de pagamento, valor pago e pagoEm"
Write-Host "  - nao consulta disponibilidade da agenda"
Write-Host ""
Write-Host "Agora execute:" -ForegroundColor Cyan
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
Write-Host "  git status"
